"use client";

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "../../lib/utils";
import { CircleAlert, CircleCheck, Info, TriangleAlert, X } from "./icons";

// Alert: generated by UIX from the design system. Same variants and sizes as the Figma component.

const alertVariants = cva(
  "flex w-full items-start border gap-3 p-4 text-fg-primary rounded-lg",
  {
    variants: {
      appearance: {
        subtle: "",
        accent: "",
        solid: "",
        outline: "",
      },
      type: {
        info: "",
        success: "",
        warning: "",
        error: "",
      },
    },
    compoundVariants: [
      { appearance: "subtle", type: "info", class: "skin-keep bg-info-subtle border-line-brand [&_[data-slot=icon]]:text-icon-brand [&_[data-slot=description]]:text-fg-secondary" },
      { appearance: "subtle", type: "success", class: "skin-keep bg-success-subtle border-line-success [&_[data-slot=icon]]:text-icon-success [&_[data-slot=description]]:text-fg-secondary" },
      { appearance: "subtle", type: "warning", class: "skin-keep bg-warning-subtle border-line-warning [&_[data-slot=icon]]:text-icon-warning [&_[data-slot=description]]:text-fg-secondary" },
      { appearance: "subtle", type: "error", class: "skin-keep bg-danger-subtle border-line-danger [&_[data-slot=icon]]:text-icon-danger [&_[data-slot=description]]:text-fg-secondary" },
      { appearance: "accent", type: "info", class: "bg-surface border-line-brand border-l-4 [&_[data-slot=icon]]:text-icon-brand [&_[data-slot=description]]:text-fg-secondary" },
      { appearance: "accent", type: "success", class: "bg-surface border-line-success border-l-4 [&_[data-slot=icon]]:text-icon-success [&_[data-slot=description]]:text-fg-secondary" },
      { appearance: "accent", type: "warning", class: "bg-surface border-line-warning border-l-4 [&_[data-slot=icon]]:text-icon-warning [&_[data-slot=description]]:text-fg-secondary" },
      { appearance: "accent", type: "error", class: "bg-surface border-line-danger border-l-4 [&_[data-slot=icon]]:text-icon-danger [&_[data-slot=description]]:text-fg-secondary" },
      { appearance: "solid", type: "info", class: "skin-solid bg-brand text-fg-on-brand border-transparent [&_[data-slot=icon]]:text-fg-on-brand [&_[data-slot=description]]:text-fg-on-brand" },
      { appearance: "solid", type: "success", class: "skin-solid bg-success text-fg-on-brand border-transparent [&_[data-slot=icon]]:text-fg-on-brand [&_[data-slot=description]]:text-fg-on-brand" },
      { appearance: "solid", type: "warning", class: "skin-solid bg-warning text-fg-primary border-transparent [&_[data-slot=icon]]:text-fg-primary [&_[data-slot=description]]:text-fg-primary" },
      { appearance: "solid", type: "error", class: "skin-solid bg-danger text-fg-on-danger border-transparent [&_[data-slot=icon]]:text-fg-on-danger [&_[data-slot=description]]:text-fg-on-danger" },
      { appearance: "outline", type: "info", class: "bg-surface border-line-brand [&_[data-slot=icon]]:text-icon-brand [&_[data-slot=description]]:text-fg-secondary" },
      { appearance: "outline", type: "success", class: "bg-surface border-line-success [&_[data-slot=icon]]:text-icon-success [&_[data-slot=description]]:text-fg-secondary" },
      { appearance: "outline", type: "warning", class: "bg-surface border-line-warning [&_[data-slot=icon]]:text-icon-warning [&_[data-slot=description]]:text-fg-secondary" },
      { appearance: "outline", type: "error", class: "bg-surface border-line-danger [&_[data-slot=icon]]:text-icon-danger [&_[data-slot=description]]:text-fg-secondary" },
    ],
    defaultVariants: {
      appearance: "subtle",
      type: "info",
    },
  },
);

const alertIcons = { info: Info, success: CircleCheck, warning: TriangleAlert, error: CircleAlert };

export interface AlertProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "title">,
    VariantProps<typeof alertVariants> {
  title?: React.ReactNode;
  /** Buttons or links under the message. */
  actions?: React.ReactNode;
  /** Shows a dismiss button and calls this when it is pressed. */
  onClose?: () => void;
}

const Alert = React.forwardRef<HTMLDivElement, AlertProps>(
  ({ className, appearance, type, title, actions, onClose, children, ...props }, ref) => {
    const Icon = alertIcons[type ?? "info"];
    return (
      <div data-slot="alert" data-kind="surface" ref={ref} role="alert" className={cn(alertVariants({ appearance, type }), className)} {...props}>
        <Icon data-slot="icon" aria-hidden className="size-5 shrink-0" />
        <div className="flex min-w-0 flex-1 flex-col gap-1">
          {title ? (
            <p data-slot="title" className="text-label-large">
              {title}
            </p>
          ) : null}
          {children ? (
            <div data-slot="description" className="text-body-small">
              {children}
            </div>
          ) : null}
          {actions ? (
            <div data-slot="actions" className="flex items-center gap-3 pt-1">
              {actions}
            </div>
          ) : null}
        </div>
        {onClose ? (
          <button type="button" aria-label="Dismiss" onClick={onClose} className="shrink-0 cursor-pointer rounded-xs opacity-80 hover:opacity-100 focus-visible:outline-none focus-visible:ring-3 focus-visible:ring-line-focus">
            <X aria-hidden className="size-4" />
          </button>
        ) : null}
      </div>
    );
  },
);
Alert.displayName = "Alert";

export { Alert, alertVariants };
